class Solution {
public:
    int minOperations(vector<int>& nums, int k) {
        bool present[101] = {false};
        for (int x : nums) {
            if (x < k) return -1;
            present[x] = true;
        }
        int count = 0;
        for (int v = k + 1; v <= 100; v++) {
            if (present[v]) count++;
        }
        return count;
    }
};
